def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    opp_d = 0
    my_d = 0
    for i in range(n):
        if history[i][0] == 'D':
            my_d += 1
        if history[i][1] == 'D':
            opp_d += 1

    w = n if n < 8 else 8
    recent_opp_d = 0
    for i in range(n - w, n):
        if history[i][1] == 'D':
            recent_opp_d += 1

    opp_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_streak += 1
        i -= 1

    unprov = 0
    punish_after = 0
    tol_after = 0
    for i in range(1, n):
        prev_my = history[i - 1][0]
        cur_opp = history[i][1]
        if prev_my == 'C' and cur_opp == 'D':
            unprov += 1
        elif prev_my == 'D' and cur_opp == 'D':
            punish_after += 1
        elif prev_my == 'D' and cur_opp == 'C':
            tol_after += 1

    if opp_d >= 3 and opp_d * 2 >= n:
        return 'D'

    if recent_opp_d >= 6:
        return 'D'

    if opp_streak >= 5:
        return 'D'

    if n >= 98:
        return 'D'

    if n >= 2 and opp_last == 'D' and history[-2][1] == 'D':
        if my_last == 'D':
            if opp_d <= max(5, n // 3) and recent_opp_d <= 4:
                return 'C'
            return 'D'
        return 'D'

    if opp_last == 'D':
        if my_last == 'C':
            if (
                n >= 2
                and history[-2][0] == 'D'
                and opp_d <= max(6, n // 2)
                and recent_opp_d <= 4
                and punish_after <= 2
            ):
                return 'C'

            if recent_opp_d >= 4 or unprov >= 4:
                return 'D'

            if opp_d <= max(3, n // 4):
                return 'C'

            return 'D'

        if recent_opp_d <= 3 and opp_d <= max(6, n // 2):
            return 'C'
        return 'D'

    if my_last == 'D':
        if recent_opp_d == 0 and opp_d <= 1 and punish_after == 0:
            return 'D'
        return 'C'

    if opp_d == 0 and n >= 25 and rng.random() < 0.008:
        return 'D'

    if (
        opp_d <= 1
        and my_d > 0
        and recent_opp_d == 0
        and punish_after == 0
        and tol_after > 0
        and rng.random() < 0.03
    ):
        return 'D'

    return 'C'
